import XCTest

class ImageTapTest: XCTestCase {
    func testTapImageInPost() {
        let app = XCUIApplication()
        if app.state == .notRunning {
            app.launch()
        }

        // Wait for the app to be ready
        sleep(2)

        // Get all images in the current view
        let images = app.images

        // Find the first image that's visible (not the icons)
        for image in images.allElementsBoundByIndex {
            if image.isHittable && image.frame.size.width > 100 {
                print("Found image at: \(image.frame)")
                image.tap()
                sleep(1)
                print("Tapped image successfully")
                return
            }
        }

        XCTFail("Could not find a tappable image")
    }
}
EOF

cat > /tmp/UIInteractionTest.swift << 'EOF'
import XCTest

class UIInteractionTest: XCTestCase {

    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    func testTapImageInBluesky() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        // Get the first image that is likely the post image
        let images = app.images
        var tappedImage = false

        for image in images.allElementsBoundByIndex {
            if image.isHittable && image.frame.size.width > 80 && image.frame.size.height > 80 {
                image.tap()
                tappedImage = true
                print("Tapped image successfully at: \(image.frame)")
                break
            }
        }

        if !tappedImage {
            XCTFail("Could not find and tap an image")
        }

        // Wait for the image viewer to appear
        sleep(2)
    }
}
EOF

